class AdminManager{constructor(){this.activeTab="pending",this.init()}init(){document.addEventListener("click",async t=>{const i=t.target.closest(".admin-approve-btn");if(i){const s=i.getAttribute("data-listing-id");await this.handleApproveListing(s);return}const e=t.target.closest(".admin-reject-btn");if(e){const s=e.getAttribute("data-listing-id");await this.handleRejectListing(s);return}})}async render(){const t=document.getElementById("view-admin");if(!t)return;const i=window.authManager?window.authManager.currentUser:null,e=i&&window.ADMIN_ALLOWLIST&&window.ADMIN_ALLOWLIST.includes(i.email);if(!(i&&(i.role==="admin"||e))){t.innerHTML=`
        <div class="container section" style="max-width: 650px; text-align: center; margin: 60px auto;">
          <div style="font-size: 3.5rem; margin-bottom: 16px;">\u{1F6E1}\uFE0F</div>
          <h1 style="font-family: var(--font-serif); margin-bottom: 12px;">Admin Access Restricted</h1>
          <p style="color: var(--text-muted); font-size: 1.05rem; line-height: 1.6; margin-bottom: 24px;">
            The Travel Nexus Moderation Dashboard requires administrative privileges.
            ${i?`You are currently signed in as <strong>${i.email}</strong> with role <em>${i.role||"traveler"}</em>.`:"You are currently not signed in."}
          </p>
          <div style="background: var(--bg-cream, #FAF7F2); border: 1px solid var(--border-light, #E8E2D8); border-radius: 8px; padding: 20px; margin-bottom: 28px;">
            <p style="font-size: 0.9rem; color: var(--text-dark); margin-bottom: 12px;">
              <strong>Testing Tip:</strong> You can access this dashboard immediately using the 1-Click Admin Demo or by signing in with an authorized email in <code>window.ADMIN_ALLOWLIST</code>.
            </p>
            <button class="btn btn-primary btn-sm" onclick="window.authManager.demoLogin('admin')">
              \u{1F6E1}\uFE0F Sign in with 1-Click Admin Demo
            </button>
          </div>
          <a href="#home" class="btn btn-outline">Return to Home</a>
        </div>
      `;return}t.innerHTML=`
      <div class="container section">
        <div class="admin-loading-state">
          <p>Loading Travel Nexus Moderation Data...</p>
        </div>
      </div>
    `;try{const a=await window.firebaseService.getAdminStats(),n=await window.firebaseService.getPendingListings(),d=(await window.firebaseService.getListings()).filter(r=>r.status==="approved"),o=await window.firebaseService.getUsers();t.innerHTML=`
        <div class="container section" style="max-width: 1140px;">
          <!-- ADMIN DASHBOARD HEADER -->
          <div class="admin-dashboard-header">
            <div>
              <span class="admin-hero-kicker">Internal Control Hub</span>
              <h1 class="admin-hero-title">Travel Nexus Admin & Moderation</h1>
              <p class="admin-hero-sub">Welcome back, <strong>${i.displayName||i.email}</strong>. Review incoming boutique listings, manage user privileges, and maintain curation standards.</p>
            </div>
            <div class="admin-header-actions">
              <span class="status-pill status-approved" style="font-size: 0.85rem; padding: 6px 14px;">\u{1F6E1}\uFE0F Superadmin Active</span>
            </div>
          </div>

          <!-- PLATFORM OVERVIEW STATS TILES -->
          <div class="admin-stats-grid">
            <div class="admin-stat-card">
              <div class="admin-stat-icon">\u23F3</div>
              <div class="admin-stat-num">${a.pendingListings}</div>
              <div class="admin-stat-label">Pending Approval</div>
            </div>
            <div class="admin-stat-card">
              <div class="admin-stat-icon">\u2705</div>
              <div class="admin-stat-num">${a.approvedListings}</div>
              <div class="admin-stat-label">Published Listings</div>
            </div>
            <div class="admin-stat-card">
              <div class="admin-stat-icon">\u{1F465}</div>
              <div class="admin-stat-num">${a.totalUsers}</div>
              <div class="admin-stat-label">Registered Accounts</div>
            </div>
            <div class="admin-stat-card">
              <div class="admin-stat-icon">\u{1F5FA}\uFE0F</div>
              <div class="admin-stat-num">${a.curatedDestinations}</div>
              <div class="admin-stat-label">Flagship Destinations</div>
            </div>
          </div>

          <!-- ADMIN NAVIGATION TABS -->
          <div class="admin-nav-tabs">
            <button class="admin-tab-btn ${this.activeTab==="pending"?"active":""}" 
                    onclick="window.adminManager.switchTab('pending')">
              Moderation Queue (${n.length})
            </button>
            <button class="admin-tab-btn ${this.activeTab==="approved"?"active":""}" 
                    onclick="window.adminManager.switchTab('approved')">
              Approved Listings (${d.length})
            </button>
            <button class="admin-tab-btn ${this.activeTab==="users"?"active":""}" 
                    onclick="window.adminManager.switchTab('users')">
              User Accounts (${o.length})
            </button>
          </div>

          <!-- TAB CONTENT: PENDING LISTINGS -->
          <div id="adminTabContentPending" style="${this.activeTab==="pending"?"display: block;":"display: none;"}">
            ${this.renderPendingQueueHTML(n)}
          </div>

          <!-- TAB CONTENT: APPROVED LISTINGS -->
          <div id="adminTabContentApproved" style="${this.activeTab==="approved"?"display: block;":"display: none;"}">
            ${this.renderApprovedQueueHTML(d)}
          </div>

          <!-- TAB CONTENT: USERS ROSTER -->
          <div id="adminTabContentUsers" style="${this.activeTab==="users"?"display: block;":"display: none;"}">
            ${this.renderUsersRosterHTML(o)}
          </div>
        </div>
      `}catch(a){t.innerHTML=`
        <div class="container section" style="text-align: center; margin: 40px auto;">
          <p class="text-danger">Failed to load admin data: ${a.message}</p>
          <button class="btn btn-primary" onclick="window.adminManager.render()">Retry</button>
        </div>
      `}}switchTab(t){this.activeTab=t,this.render()}renderPendingQueueHTML(t){return!t||t.length===0?`
        <div class="admin-empty-state">
          <div style="font-size: 2.5rem; margin-bottom: 12px;">\u{1F389}</div>
          <h3>Queue is All Clear!</h3>
          <p class="text-muted">No listings are currently pending moderation review.</p>
        </div>
      `:`
      <div class="admin-queue-list">
        ${t.map(i=>this.renderModerationCardHTML(i)).join("")}
      </div>
    `}renderApprovedQueueHTML(t){return!t||t.length===0?`
        <div class="admin-empty-state">
          <p class="text-muted">No approved listings yet.</p>
        </div>
      `:`
      <div class="admin-queue-list">
        ${t.map(i=>`
          <div class="admin-mod-card">
            <div class="admin-mod-header">
              <div>
                <span class="status-pill status-approved">ACTIVE PUBLISHED</span>
                <h3 style="font-size: 1.25rem; margin-top: 6px;">${i.title}</h3>
                <span class="text-muted" style="font-size: 0.85rem;">Hosted by ${i.hostName||i.hostEmail} \u2022 ${i.location}</span>
              </div>
              <div>
                <button class="btn btn-outline btn-sm admin-reject-btn text-danger" data-listing-id="${i.id}">
                  Unpublish / Reject
                </button>
              </div>
            </div>
            <div style="display: flex; gap: 14px; margin-top: 14px; align-items: center;">
              <img src="${i.photos&&i.photos[0]?i.photos[0]:"images/placeholder.jpg"}" alt="${i.title}" style="width: 100px; height: 70px; object-fit: cover; border-radius: 6px;" />
              <p style="font-size: 0.9rem; color: var(--text-dark); margin: 0;">${i.tagline||i.description}</p>
            </div>
          </div>
        `).join("")}
      </div>
    `}renderUsersRosterHTML(t){return!t||t.length===0?`
        <div class="admin-empty-state">
          <p class="text-muted">No registered users in database.</p>
        </div>
      `:`
      <div class="admin-users-table-wrapper">
        <table class="admin-users-table">
          <thead>
            <tr>
              <th>User</th>
              <th>Email</th>
              <th>Role</th>
              <th>Wishlist Items</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            ${t.map(i=>`
              <tr>
                <td><strong>${i.displayName||"Anonymous Member"}</strong></td>
                <td>${i.email}</td>
                <td><span class="status-pill status-${i.role||"traveler"}">${(i.role||"traveler").toUpperCase()}</span></td>
                <td>${i.wishlist?i.wishlist.length:0} items</td>
                <td><span class="badge-active">Active</span></td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    `}renderModerationCardHTML(t){const i=t.coordinates?`${t.coordinates[0]}\xB0 N, ${t.coordinates[1]}\xB0 E`:"Not specified",e=t.photos||[];return`
      <div class="admin-mod-card" id="mod-card-${t.id}">
        <div class="admin-mod-header">
          <div>
            <span class="status-pill status-pending">PENDING APPROVAL</span>
            <span class="admin-mod-type-pill">${(t.type||"stay").toUpperCase()}</span>
            <h3 class="admin-mod-title">${t.title}</h3>
            <div class="admin-mod-meta">
              <span>Host: <strong>${t.hostName||t.hostEmail}</strong></span>
              <span>\u2022</span>
              <span>${t.state||"India"}</span>
              <span>\u2022</span>
              <span>Submitted ${t.createdAt?new Date(t.createdAt).toLocaleDateString("en-IN"):"Recently"}</span>
            </div>
          </div>
          <div class="admin-mod-actions">
            <button type="button" class="btn btn-primary btn-sm admin-approve-btn" data-listing-id="${t.id}">
              \u2713 Approve & Publish
            </button>
            <button type="button" class="btn btn-outline btn-sm admin-reject-btn text-danger" data-listing-id="${t.id}">
              \u2715 Reject
            </button>
          </div>
        </div>

        <div class="admin-mod-details-grid">
          <div class="admin-mod-info-col">
            <p><strong>Category:</strong> ${t.category||"Boutique"}</p>
            <p><strong>Tagline:</strong> "${t.tagline||""}"</p>
            <p><strong>Location:</strong> ${t.location} (${i})</p>
            <p><strong>Price:</strong> \u20B9${(t.price||0).toLocaleString("en-IN")} / ${t.type==="dining"?"seat":"night"}</p>
            <p><strong>Description:</strong> ${t.description||""}</p>
            
            ${t.dishes&&t.dishes.length>0?`
              <div style="margin-top: 10px;">
                <strong>Specialty Dishes (${t.dishes.length}):</strong>
                <ul style="margin: 6px 0 0 16px; font-size: 0.85rem;">
                  ${t.dishes.map(s=>`<li><strong>${s.name}</strong> (${s.diet}): ${s.description}</li>`).join("")}
                </ul>
              </div>
            `:""}

            <!-- UPLOADED PHOTOS GALLERY -->
            <div class="admin-mod-photos-label">Uploaded Photos (${e.length}):</div>
            <div class="admin-mod-photos-strip">
              ${e.map((s,a)=>`
                <a href="${s}" target="_blank" rel="noopener" title="Open full photo #${a+1}">
                  <img src="${s}" alt="Listing photo ${a+1}" class="admin-mod-photo-thumb" />
                </a>
              `).join("")}
            </div>
          </div>

          <!-- LIVE DESTINATION/STAY CARD PREVIEW (Exact site card markup contract) -->
          <div class="admin-mod-preview-col">
            <div class="admin-mod-preview-kicker">Live Visitor Card Preview</div>
            <article class="destination-card admin-live-preview-card">
              <div class="dest-img-box">
                <img src="${e[0]||"images/placeholder.jpg"}" alt="${t.title}" loading="lazy" />
                <div class="dest-price-badge">From <span>\u20B9${(t.price||0).toLocaleString("en-IN")}</span> /day</div>
                <div class="dest-wishlist-btn">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path>
                  </svg>
                </div>
              </div>
              <div class="dest-content">
                <div class="dest-header">
                  <h3 class="dest-title">${t.title}</h3>
                  <div class="dest-rating">
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"></polygon></svg>
                    <span>5.0</span>
                  </div>
                </div>
                <div class="dest-region">
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"></path><circle cx="12" cy="10" r="3"></circle></svg>
                  ${t.location}
                </div>
                <p class="dest-tagline">${t.tagline||t.description}</p>
                <div class="dest-attractions-chips">
                  <span class="dest-chip">${t.category||"Boutique"}</span>
                  <span class="dest-chip">${t.state||"India"}</span>
                </div>
                <div class="dest-footer">
                  <div class="dest-time">Host: <strong>${(t.hostName||"Verified").split(" ")[0]}</strong></div>
                  <button class="btn btn-outline btn-sm">Explore Guide</button>
                </div>
              </div>
            </article>
          </div>
        </div>
      </div>
    `}async handleApproveListing(t){if(t)try{window.showToast("Approving listing...","info"),await window.firebaseService.updateListingStatus(t,"approved"),window.showToast("Listing approved & published to live feed!","success"),await this.render()}catch(i){window.showToast("Error approving listing: "+i.message,"error")}}async handleRejectListing(t){if(t&&confirm("Are you sure you want to reject/unpublish this listing?"))try{window.showToast("Updating listing status...","info"),await window.firebaseService.updateListingStatus(t,"rejected"),window.showToast("Listing rejected.","info"),await this.render()}catch(i){window.showToast("Error rejecting listing: "+i.message,"error")}}}typeof window<"u"&&(window.AdminManager=AdminManager,window.adminManager=new AdminManager),typeof module<"u"&&module.exports&&(module.exports={AdminManager});
